using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);
var errors = new List<(string project, string code, string file, int line, string message)>();
var warnings = new List<(string project, string code, string file, int line, string message)>();

build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = (BaseNode)e;
    while (node.Parent != null) {
        node = (BaseNode)node.Parent;
        if (node is Project p) { proj = p.Name; break; }
    }
    errors.Add((proj, e.Code ?? "", e.File ?? "", e.LineNumber, e.Text ?? ""));
});

build.VisitAllChildren<Warning>(w => {
    var proj = "";
    var node = (BaseNode)w;
    while (node.Parent != null) {
        node = (BaseNode)node.Parent;
        if (node is Project p) { proj = p.Name; break; }
    }
    warnings.Add((proj, w.Code ?? "", w.File ?? "", w.LineNumber, w.Text ?? ""));
});

Console.WriteLine($"=== BUILD RESULT: {(build.Succeeded ? "SUCCESS" : "FAILED")} ===");
Console.WriteLine($"\n=== ERRORS ({errors.Count}) ===");
foreach (var e in errors)
    Console.WriteLine($"  [{e.project}] {e.code} at {e.file}({e.line}): {e.message}");

Console.WriteLine($"\n=== WARNINGS ({warnings.Count}) ===");
foreach (var w in warnings)
    Console.WriteLine($"  [{w.project}] {w.code} at {w.file}({w.line}): {w.message}");
